 function smoothRegions(pixels,labels,alpha,w,h,palette,amount){const total=w*h;let current=labels,next=new Uint8Array(total);for(let pass=0;pass<2;pass++){for(let y=0;y<h;y++)for(let x=0;x<w;x++){const i=y*w+x;if(alpha[i]<96){next[i]=255;continue}const idx=i*4,r=pixels[idx],g=pixels[idx+1],b=pixels[idx+2],own=current[i],candidates=[own];if(x)candidates.push(current[i-1]);if(x+1<w)candidates.push(current[i+1]);if(y)candidates.push(current[i-w]);if(y+1<h)candidates.push(current[i+w]);let best=own,bestCost=Infinity;for(let a=0;a<candidates.length;a++){const c=candidates[a];let seen=false;for(let z=0;z<a;z++)if(candidates[z]===c)seen=true;if(seen)continue;const p=palette[c],colorCost=((r-p.r)**2+(g-p.g)**2+(b-p.b)**2)/3;let breaks=0;if(x&&current[i-1]!==c)breaks++;if(x+1<w&&current[i+1]!==c)breaks++;if(y&&current[i-w]!==c)breaks++;if(y+1<h&&current[i+w]!==c)breaks++;const cost=colorCost+amount*breaks;if(cost<bestCost){bestCost=cost;best=c}}next[i]=best}current=next;next=new Uint8Array(total)}return current}
 function loopsForColor(labels,color,w,h){const stride=w+1,starts=new Map(),from=[],to=[],dirs=[],used=[];const add=(x1,y1,x2,y2,d)=>{const e=from.length;from.push(y1*stride+x1);to.push(y2*stride+x2);dirs.push(d);used.push(0);const k=from[e];let a=starts.get(k);if(!a){a=[];starts.set(k,a)}a.push(e)};for(let y=0;y<h;y++){let row=y*w;for(let x=0;x<w;x++){if(labels[row+x]!==color)continue;const i=row+x;if(y===0||labels[i-w]!==color)add(x,y,x+1,y,0);if(x===w-1||labels[i+1]!==color)add(x+1,y,x+1,y+1,1);if(y===h-1||labels[i+w]!==color)add(x+1,y+1,x,y+1,2);if(x===0||labels[i-1]!==color)add(x,y+1,x,y,3)}}const loops=[];for(let e=0;e<from.length;e++){if(used[e])continue;const points=[];let cur=e,guard=0;while(!used[cur]&&guard++<from.length+1){used[cur]=1;points.push(from[cur]);const end=to[cur];if(end===from[e])break;const options=starts.get(end)||[];let pick=-1,score=99;for(const candidate of options){if(used[candidate])continue;const turn=(dirs[candidate]-dirs[cur]+4)%4;const rank=turn===1?0:turn===0?1:turn===3?2:3;if(rank<score){pick=candidate;score=rank}}if(pick<0)break;cur=pick}if(points.length>=3)loops.push(points.map(v=>({x:v%stride,y:Math.floor(v/stride)})))}return loops}
