 function roundedPath(raw,tolerance,rounding){let p=raw;if(p.length>3&&p[0].x===p[p.length-1].x&&p[0].y===p[p.length-1].y)p=p.slice(0,-1);if(p.length<3)return'';let far=1,maxDist=0;for(let i=1;i<p.length;i++){const d=(p[i].x-p[0].x)**2+(p[i].y-p[0].y)**2;if(d>maxDist){maxDist=d;far=i}}const a=simplify(p.slice(0,far+1),tolerance),b=simplify(p.slice(far).concat([p[0]]),tolerance),reduced=a.concat(b.slice(1,-1));if(reduced.length<3)return'';const n=reduced.length,before=[],after=[];for(let i=0;i<n;i++){const a=reduced[(i+n-1)%n],v=reduced[i],b=reduced[(i+1)%n],la=Math.hypot(v.x-a.x,v.y-a.y),lb=Math.hypot(b.x-v.x,b.y-v.y);const cut=Math.min(rounding,la*.18,lb*.18);before.push({x:v.x+(a.x-v.x)*(cut/(la||1)),y:v.y+(a.y-v.y)*(cut/(la||1))});after.push({x:v.x+(b.x-v.x)*(cut/(lb||1)),y:v.y+(b.y-v.y)*(cut/(lb||1))})}let d=`M${before[0].x.toFixed(2)} ${before[0].y.toFixed(2)}`;for(let i=0;i<n;i++){const v=reduced[i],next=(i+1)%n;d+=`Q${v.x.toFixed(2)} ${v.y.toFixed(2)} ${after[i].x.toFixed(2)} ${after[i].y.toFixed(2)}L${before[next].x.toFixed(2)} ${before[next].y.toFixed(2)}`}return d+'Z'}
