 const commands=d=>{const tokens=d.match(/[MQLZ]|-?\d*\.?\d+(?:e[-+]?\d+)?/gi)||[],out=[];let i=0,x=0,y=0,sx=0,sy=0;while(i<tokens.length){const op=tokens[i++];if(op==='M'){x=+tokens[i++];y=+tokens[i++];sx=x;sy=y;out.push(['M',x,y])}else if(op==='L'){x=+tokens[i++];y=+tokens[i++];out.push(['L',x,y])}else if(op==='Q'){const cx=+tokens[i++],cy=+tokens[i++],nx=+tokens[i++],ny=+tokens[i++];out.push(['Q',x,y,cx,cy,nx,ny]);x=nx;y=ny}else if(op==='Z'){out.push(['Z']);x=sx;y=sy}}return out};
 const pdfPath=(ops,h)=>{let x=0,y=0,sx=0,sy=0,out=[];ops.forEach(o=>{if(o[0]==='M'){const nx=o[1],ny=h-o[2];out.push(`${nx-x} ${ny-y} m`);x=nx;y=ny;sx=x;sy=y}else if(o[0]==='L'){const nx=o[1],ny=h-o[2];out.push(`${nx-x} ${ny-y} l`);x=nx;y=ny}else if(o[0]==='Q'){const cx=o[3],cy=h-o[4],nx=o[5],ny=h-o[6],c1x=x+2*(cx-x)/3,c1y=y+2*(cy-y)/3,c2x=nx+2*(cx-nx)/3,c2y=ny+2*(cy-ny)/3;out.push(`${c1x-x} ${c1y-y} ${c2x-c1x} ${c2y-c1y} ${nx-c2x} ${ny-c2y} c`);x=nx;y=ny}else{out.push('h');x=sx;y=sy}});return out.join('\n')};
